// ── Animation DSL ────────────────────────────────────────────────────────────
// The DSL is the single source of truth for a video. It is generated by a local
// Ollama model, editable by the user, and consumed by the deterministic renderer.

export type ScenePosition = 'top' | 'center' | 'bottom' | 'top-center';

/** Named ThemePack id from lib/themes.ts, or a partial pack override. */
export type SceneTheme = string | Record<string, unknown>;

/** Transition into this scene from the previous primary card. */
export type SceneTransition =
  | 'none'
  | 'fade'
  | 'slide'
  | 'push'
  | 'zoom'
  | 'dissolve'
  | 'wipe'
  | 'iris'
  | 'bars'
  | 'sweep';

export interface BaseScene {
  /** Seconds from the start of the video. */
  startTime: number;
  /** Seconds this scene is on screen. */
  duration: number;
  /** Spoken voiceover for this scene, synthesized locally (Kokoro TTS). */
  narration?: string;
  /** Set by the narration pipeline: seconds the synthesized speech lasts. */
  narrationDuration?: number;
  /** ThemePack id (e.g. "nord") or partial pack override for this scene. */
  theme?: SceneTheme;
  /** Partial ThemePack merge on top of `theme`. */
  style?: Record<string, unknown>;
  /** How this primary card enters (ignored for overlays). */
  transition?: SceneTransition;
}

export interface CodeScene extends BaseScene {
  type: 'code';
  language: string;
  code: string;
  /** Characters per second while typing in. */
  typingSpeed: number;
  highlightSyntax?: boolean;
  cursorVisible?: boolean;
  fontSize?: number;
  title?: string;
}

export interface TerminalScene extends BaseScene {
  type: 'terminal';
  output: string;
  command?: string;
  prompt?: string;
  typingSpeed: number;
  fontSize?: number;
  sound?: boolean;
}

export interface TextScene extends BaseScene {
  type: 'text';
  content: string;
  position: ScenePosition;
  fontSize?: number;
  color?: string;
  fadeIn?: number;
  fadeOut?: number;
}

export interface ClickScene extends BaseScene {
  type: 'click';
  button: string;
  sound?: boolean;
}

export interface WaitScene extends BaseScene {
  type: 'wait';
}

export interface HighlightScene extends BaseScene {
  type: 'highlight';
  startLine: number;
  endLine: number;
  color?: string;
  /** Word anchor: the highlight fires the moment this word is spoken in the
   *  overlaid code scene's narration (e.g. "closure"). Beats startTime. */
  syncWord?: string;
}

export interface TitleScene extends BaseScene {
  type: 'title';
  text: string;
  subtitle?: string;
  accentColor?: string;
}

/** Code evolving from `before` to `after`: kept lines stay, removed lines
 *  collapse away, added lines are typed in — the core tutorial pattern. */
export interface DiffScene extends BaseScene {
  type: 'diff';
  language: string;
  before: string;
  after: string;
  /** Characters per second while typing added lines. */
  typingSpeed: number;
  fontSize?: number;
  title?: string;
}

// ── Sprite / template animation ────────────────────────────────────────────────
// A generic, deterministic visual layer: a named template (drawn from canvas
// primitives in lib/templates.ts) whose transform is driven by keyframes. This is
// what lets prompts like "a boy jumping in the air" render without bespoke code.
export type Easing = 'linear' | 'easeInOut' | 'easeInCubic' | 'easeOutCubic' | 'easeOutBack';

/** Which transform channel a keyframe drives. */
export type AnimProp = 'x' | 'y' | 'scaleX' | 'scaleY' | 'rotation' | 'opacity';

export interface Keyframe {
  prop: AnimProp;
  /** For x/y: fraction of width/height (0..1, absolute). scale: multiplier of base
   *  scale (1 = natural). rotation: degrees. opacity: 0..1. */
  from: number;
  to: number;
  /** Seconds relative to the scene's own startTime. */
  start: number;
  duration: number;
  easing?: Easing;
}

export interface SpriteScene extends BaseScene {
  type: 'sprite';
  /** A key registered in lib/templates.ts, e.g. 'boy' | 'ball' | 'cloud'. */
  template: string;
  /** Base anchor position as fractions of width/height (0..1). */
  x: number;
  y: number;
  /** Base size multiplier applied on top of the template's natural size. */
  scale: number;
  /** Free-form template params, e.g. { color: '#22d3ee' }. */
  props: Record<string, any>;
  animations: Keyframe[];
}

// ── Card scenes ────────────────────────────────────────────────────────────────
// Full-frame explanatory beats between code sections. Like title cards, an
// active card owns the frame.

export interface BulletsScene extends BaseScene {
  type: 'bullets';
  title?: string;
  /** Short points, revealed one by one in sync with the narration. */
  items: string[];
}

export interface DiagramNode {
  id: string;
  label: string;
  /** Position as fractions of width/height (0..1). */
  x: number;
  y: number;
  color?: string;
}

export interface DiagramEdge {
  from: string;
  to: string;
  label?: string;
}

export interface DiagramScene extends BaseScene {
  type: 'diagram';
  title?: string;
  nodes: DiagramNode[];
  edges: DiagramEdge[];
  /** clean (default) or sketch (RoughJS-inspired hand-drawn strokes). */
  aesthetic?: 'clean' | 'sketch';
  /** 'auto' → dagre lays the graph out (LLM can omit x/y); 'manual' → honor x/y.
   *  Default: auto-detected (auto when coordinates are missing/degenerate). */
  layout?: 'auto' | 'manual';
  /** Rank direction for auto layout: 'LR' (default) or 'TB'. */
  layoutDir?: 'LR' | 'TB';
}

export interface QuoteScene extends BaseScene {
  type: 'quote';
  text: string;
  attribution?: string;
}

export interface BigStatScene extends BaseScene {
  type: 'bigstat';
  /** Headline value, e.g. "10x" or "300ms". Numeric part counts up. */
  value: string;
  label: string;
}

/** Section divider: "01 — Setting up". */
export interface ChapterScene extends BaseScene {
  type: 'chapter';
  number?: number;
  text: string;
}

/** The studio mascot appears and acts — an overlay on the current moment.
 *  With `line` set it points at that line of the visible code panel. */
export interface MascotScene extends BaseScene {
  type: 'mascot';
  action: 'wave' | 'point' | 'think' | 'celebrate' | 'shocked' | 'idle';
  /** 1-based line of the current code panel to aim at (point/look). */
  line?: number;
  /** Which side of the code panel to stand on (default right). */
  side?: 'left' | 'right';
}

/** Interactive checkpoint. The player pauses here and waits for an answer;
 *  in exported video it becomes a timed question → answer reveal. */
export interface QuizScene extends BaseScene {
  type: 'quiz';
  question: string;
  options: string[];
  answerIndex: number;
  explanation?: string;
}

/** One graded check: evaluate `expression` against the learner's code and
 *  compare its printed result to `expected` (both trimmed). */
export interface ChallengeTest {
  expression: string;
  expected: string;
}

/** A real coding challenge (LEAP 3). The player pauses, the learner writes code
 *  in an editor, and it's RUN against `tests`. Progression reflects mastery.
 *  Export renders it as a "try this" card with the solution revealed. */
export interface ChallengeScene extends BaseScene {
  type: 'challenge';
  language: string;
  /** What to build, in one or two sentences. */
  prompt: string;
  /** Scaffold the learner starts from (a signature + TODO). */
  starterCode: string;
  /** A correct solution (used for export reveal and as a fallback). */
  solution: string;
  tests: ChallengeTest[];
  hint?: string;
  /** Short concept tag for the learner model, e.g. "list comprehensions". */
  concept?: string;
}

// ── Concept visualization (LEAP 4) ──────────────────────────────────────────────
// Animate the IDEA behind the code — an array being sorted, a pointer walking, the
// call stack growing, a variable accumulating. One general step-based model covers
// most intro-CS concepts. Each step carries the FULL state (not deltas); the
// renderer tweens between consecutive steps (values pop, pointers glide, stack
// frames push/pop).
export interface VizPointer {
  /** Label shown on the pointer, e.g. "i", "left", "head". */
  name: string;
  /** Which array index it points at. */
  index: number;
}

export interface VizStep {
  /** One short line describing this step (shown on screen, synced to narration). */
  caption?: string;
  /** Full array state at this step (cell values as strings). */
  array?: string[];
  /** Indices to highlight (accent). */
  highlight?: number[];
  /** Two indices being compared (amber). */
  compare?: [number, number];
  /** Indices considered done/sorted (green). */
  done?: number[];
  /** Labeled pointers onto array cells. */
  pointers?: VizPointer[];
  /** Named variables to show as boxes, e.g. { sum: "6", i: "2" }. */
  vars?: Record<string, string>;
  /** Full call/DS stack, bottom → top. */
  stack?: string[];
}

export interface VizScene extends BaseScene {
  type: 'viz';
  title?: string;
  /** Primary focus, a layout hint. */
  vizKind?: 'array' | 'stack' | 'vars';
  steps: VizStep[];
}

// ── IDE template (flagship) ─────────────────────────────────────────────────────
// A single full-frame scene that OWNS the moment (like a card) and plays an
// internal sequence of steps: open/create files, type code, run terminal
// commands. The file tree + editor tabs + integrated terminal stay on screen and
// evolve together, paced across the (narration-stretched) scene duration. One
// `ide` scene replaces a whole screen-recording of VS Code.

export interface IdeFile {
  /** Path with '/' separators; folders are inferred, e.g. "src/app.py". */
  path: string;
  /** Language for syntax highlighting (inferred from extension if omitted). */
  language?: string;
  /** Contents shown when the file first appears (usually "" — it gets typed). */
  code?: string;
}

/** What a single IDE step does. */
export type IdeAction =
  /** Focus a file tab (the file must already exist in the tree). */
  | { kind: 'open'; file: string }
  /** Create a NEW file: the cursor clicks the explorer, an inline name field
   *  types the filename, and the file pops into the tree and opens. */
  | { kind: 'create'; file: string }
  /** Type `code` into `file` (typewriter). Reveals only the tail that changed
   *  from the file's previous snapshot, so successive types read as edits. */
  | { kind: 'type'; file: string; code: string; typingSpeed?: number }
  /** Run `command` in the integrated terminal; `output` streams in beneath it.
   *  `creates` lists files the command scaffolds (e.g. `npm create vite`) — they
   *  pop into the explorer tree when the command runs, so later steps can open
   *  and edit them. */
  | { kind: 'run'; command: string; output?: string; creates?: string[] }
  /** Glow lines `startLine`..`endLine` of the active file. */
  | { kind: 'highlight'; file?: string; startLine: number; endLine: number }
  /** Teach without changing the workspace: hold everything, glow lines when
   *  given (like highlight) or zoom the terminal (`terminal:true`) while the
   *  step's narration explains what's on screen. THE explanation beat. */
  | { kind: 'explain'; file?: string; startLine?: number; endLine?: number; terminal?: boolean };

export interface IdeStep {
  /** Short on-screen caption for this step (optional). */
  caption?: string;
  action: IdeAction;
  /** What the teacher SAYS during this step (2-4 spoken sentences). The step
   *  starts exactly when its first sentence is spoken and holds while the
   *  voice continues — this is what syncs typing/highlights/runs to speech. */
  narration?: string;
  /** Optional keystroke/shortcut chip to flash for this step, e.g. "⌘S". */
  key?: string;
  /** Relative pacing weight — fallback only, when steps carry no narration. */
  weight?: number;
}

export interface IdeScene extends BaseScene {
  type: 'ide';
  /** Workspace name shown atop the file explorer. */
  project?: string;
  /** Git branch shown in the status bar (default "main"). */
  branch?: string;
  /** Show the File/Edit/… menu bar (default true). */
  showMenu?: boolean;
  /** Initial files seeding the tree (steps may add more via `open`/`type`). */
  files: IdeFile[];
  steps: IdeStep[];
  /** Computed by the narration pipeline (never authored): scene-relative start
   *  time of each step = the moment its first narration sentence is spoken. */
  stepNarrationTimes?: number[];
}

// ── Terminal / CLI session template ─────────────────────────────────────────────
// A full-screen terminal running a sequence of real commands — replaces an
// asciinema/terminal screencast.
export interface CliCommand {
  /** The command typed at the prompt. */
  command: string;
  /** What it prints (streams in beneath). */
  output?: string;
  /** Relative pacing weight (default from output length). */
  weight?: number;
}
export interface CliScene extends BaseScene {
  type: 'cli';
  /** Window title, e.g. "zsh — ~/project". */
  title?: string;
  /** Shown in the prompt, e.g. "~/todo-api". */
  cwd?: string;
  commands: CliCommand[];
}

// ── Browser / web page model (shared by browser + split templates) ───────────────
export type BrowserBlock =
  | { kind: 'nav'; brand: string; links?: string[] }
  | { kind: 'hero'; heading: string; sub?: string; cta?: string }
  | { kind: 'button'; label: string; primary?: boolean }
  | { kind: 'card'; title: string; body?: string }
  | { kind: 'text'; text: string }
  | { kind: 'input'; placeholder: string; value?: string }
  | { kind: 'image'; label?: string }
  | { kind: 'code'; text: string }
  /** Sanitized HTML snippet rendered as a custom page section. */
  | { kind: 'html'; html: string }
  /** Google-like search box (query types in). */
  | { kind: 'search'; query: string; engine?: string }
  /** Search engine results page. */
  | { kind: 'serp'; results: { title: string; url: string; snippet: string }[] }
  /** Documentation page with sidebar. */
  | { kind: 'docs'; heading: string; body: string; sidebar?: string[]; active?: string; highlight?: string };

export interface BrowserTab {
  title: string;
  url?: string;
  active?: boolean;
}

export interface BrowserScene extends BaseScene {
  type: 'browser';
  /** Address-bar URL. */
  url: string;
  /** Tab title. */
  title?: string;
  /** Optional multi-tab strip (Chrome-like). */
  tabs?: BrowserTab[];
  /**
   * Page chrome: light or dark page surface.
   * (Scene ThemePack lives on BaseScene.theme — use pageTheme for the page itself.)
   */
  pageTheme?: 'light' | 'dark';
  /** @deprecated Use pageTheme. Kept for LLM/scaffold compat. */
  theme?: 'light' | 'dark' | SceneTheme;
  /** Page blocks, revealed one-by-one across the (narrated) duration. Used as a
   *  fallback mockup when no real screenshot is available for `url`. */
  blocks: BrowserBlock[];
  /** Index of a block (button) the cursor clicks near the end (optional). */
  clickBlock?: number;
  /** Path/data-URL of a REAL screenshot of `url`, captured by the browser-shot
   *  pre-pass (lib/render/capture-page.ts). Never authored — when present the
   *  renderer composites the live page instead of drawing mock blocks. */
  shot?: string;
}

// ── Real browser recording (from scripts/capture-browser.mts) ───────────────────
// Plays a deterministic capture of a REAL web page inside the lesson, framed in
// the same window chrome as the mock browser. Put clips in public/captures/.
export interface BrowserRecScene extends BaseScene {
  type: 'browserrec';
  /** Video URL, e.g. "/captures/search-demo.mp4". */
  src: string;
  /** Window title. */
  title?: string;
  /** Address-bar URL shown in the chrome. */
  url?: string;
  /** Video seconds to start from (default 0). */
  clipStart?: number;
}

// ── Split: editor + live preview ────────────────────────────────────────────────
export interface SplitStep {
  caption?: string;
  /** Full code snapshot for this step (typed on the left). */
  code: string;
  /** The page the code produces (shown on the right). */
  blocks: BrowserBlock[];
  weight?: number;
}
export interface SplitScene extends BaseScene {
  type: 'split';
  language: string;
  filename?: string;
  url?: string;
  pageTheme?: 'light' | 'dark';
  /** @deprecated Use pageTheme. */
  theme?: 'light' | 'dark' | SceneTheme;
  steps: SplitStep[];
}

// ── Composite layout (multi-surface panes) ──────────────────────────────────────
export type LayoutPreset = 'ide-browser' | 'cli-browser' | 'ide-only' | 'ide-cli' | 'custom';

export interface LayoutRegion {
  /** Which surface to draw in this pane. */
  type: 'ide' | 'browser' | 'cli';
  /** Normalized rect inside the card frame (0..1). Defaults from preset. */
  rect?: { x: number; y: number; w: number; h: number };
  /** Surface-specific props (subset of IdeScene / BrowserScene / CliScene). */
  project?: string;
  files?: IdeFile[];
  steps?: IdeStep[];
  url?: string;
  title?: string;
  pageTheme?: 'light' | 'dark';
  blocks?: BrowserBlock[];
  clickBlock?: number;
  cwd?: string;
  commands?: CliCommand[];
}

export interface LayoutScene extends BaseScene {
  type: 'layout';
  preset?: LayoutPreset;
  /** Which region is "active" for camera focus (0-based). */
  focus?: number;
  regions: LayoutRegion[];
}

// ── API / request demo ──────────────────────────────────────────────────────────
export interface ApiScene extends BaseScene {
  type: 'api';
  method: string;
  url: string;
  /** Optional request headers shown in the Postman-style card. */
  headers?: Record<string, string>;
  /** Optional query string params (merged into the displayed URL bar). */
  query?: Record<string, string>;
  requestBody?: string;
  status: number;
  statusText?: string;
  /** Response body (JSON), typed into the response pane. */
  response: string;
}

// ── Pull-request / diff review ──────────────────────────────────────────────────
// A GitHub-style unified diff, reviewed top-to-bottom with the voice.
export interface PrScene extends BaseScene {
  type: 'pr';
  /** PR title shown in the window bar. */
  title?: string;
  filename: string;
  language?: string;
  before: string;
  after: string;
}

// ── Spaced-review opener (template 24) ───────────────────────────────────────────
// A 30-second recall beat that opens a later lesson: pose a question about an
// earlier concept, hold a breath, then reveal the answer. Interleaved testing
// (Szpunar) — cheap for a generator, almost nobody does it in video. The player
// can source `concept` from FSRS (lib/mastery.ts) to review what's actually weak.
export interface RecallScene extends BaseScene {
  type: 'recall';
  /** The recall question, e.g. "What does a cleanup function return?" */
  question: string;
  /** The answer, revealed after a deliberate pause. */
  answer: string;
  /** Concept tag for the learner model, e.g. "closures". */
  concept?: string;
  /** Where it came from, e.g. "Lesson 2". */
  source?: string;
}

// ── Cheat-sheet summary (template 22) ────────────────────────────────────────────
// The end-of-lesson takeaway card: the concepts, the one-line snippets, the
// gotchas — rendered as a designed surface and exportable as a still artifact.
export interface CheatsheetItem {
  /** Concept / heading, e.g. "map()". */
  label: string;
  /** A short code snippet (rendered in mono), e.g. "arr.map(f)". */
  code?: string;
  /** One-line takeaway or gotcha (rendered in sans). */
  note?: string;
}
export interface CheatsheetScene extends BaseScene {
  type: 'cheatsheet';
  title?: string;
  items: CheatsheetItem[];
}

export type Scene =
  | CodeScene
  | TerminalScene
  | TextScene
  | ClickScene
  | WaitScene
  | HighlightScene
  | TitleScene
  | DiffScene
  | SpriteScene
  | BulletsScene
  | DiagramScene
  | QuoteScene
  | BigStatScene
  | ChapterScene
  | MascotScene
  | QuizScene
  | ChallengeScene
  | VizScene
  | IdeScene
  | CliScene
  | BrowserScene
  | BrowserRecScene
  | SplitScene
  | ApiScene
  | PrScene
  | LayoutScene
  | RecallScene
  | CheatsheetScene;

/** Course / lesson brand kit applied as default theme accent. */
export interface BrandKit {
  name?: string;
  accent?: string;
  logoUrl?: string;
}

/** Overlay scene types that stack on top of a primary card. */
export const OVERLAY_TYPES = new Set(['mascot', 'highlight', 'text', 'sprite', 'click']);

/** Primary full-frame card types (one owns the frame at a time). */
export const PRIMARY_CARD_TYPES = new Set([
  'title', 'chapter', 'bullets', 'diagram', 'quote', 'bigstat', 'quiz', 'challenge', 'viz',
  'ide', 'cli', 'browser', 'browserrec', 'split', 'api', 'pr', 'layout',
  'recall', 'cheatsheet',
]);

export interface AnimationDSL {
  title: string;
  duration: number;
  fps: number;
  width: number;
  height: number;
  backgroundColor: string;
  /** Default ThemePack id or partial override for the whole lesson. */
  theme?: SceneTheme;
  /** Brand kit — accent overrides the active theme. */
  brand?: BrandKit;
  /** Kokoro voice id for narration, e.g. "af_heart". */
  voice?: string;
  /** Burn narration subtitles into the frame (default true when narration exists). */
  captions?: boolean;
  /** Play keystroke / UI sound effects (default true). */
  sfx?: boolean;
  /** Play the soft ambient music bed under the lesson (default true). */
  music?: boolean;
  scenes: Scene[];
}
